import {randomUUID} from 'node:crypto';
import {Request,Response} from 'express';
import {z} from 'zod';
import {FirebaseService} from './firebase.service.js';
import {ASSET_TYPES,assetPath} from './asset-paths.service.js';
import {requireUser} from './stripe-auth.service.js';
import {CONCIERGE_PERMISSIONS,delegatedAssets,assetPermission,activeDelegation,conciergeBookingView} from './asset-delegation.js';
import {ownerCustomerRows} from './owner-customers.service.js';
import {reservationView} from './reservation-compatibility.js';
const fail=(code:string,status=403)=>Object.assign(new Error(code),{status});
const administrator=(p:any)=>p?.isAdmin===true||p?.roles?.admin===true||['admin','superadmin'].includes(String(p?.role||'').toLowerCase());
const permissions=z.object({content:z.boolean(),bookings:z.boolean(),customers:z.boolean(),payments:z.boolean()}).strict().refine(p=>Object.values(p).some(Boolean),'permission_required');
export class ConciergeService{
 constructor(private store:FirebaseService){}
 private async identity(req:Request){const claims=await this.grantIdentity(req);return{uid:claims.uid,claims,root:(await this.store.db.ref().once('value')).val()||{}};}
 private async grantIdentity(req:Request){const token=/^Bearer\s+(.+)$/i.exec(String(req.headers.authorization||''))?.[1];if(!token)throw fail('authentication_required',401);let user:any;try{user=await this.store.auth.verifyIdToken(token);}catch{throw fail('authentication_required',401);}return user;}
 private scope(req:Request){const type=String(req.params.type),id=String(req.params.id);assetPath(type,id);return{type,id};}
 private allowed(root:any,uid:string,type:string,id:string,claimAdmin=false){const a=root.assets?.[type]?.[id];return !!a&&!a.deletedAt&&a.ownerId===uid;}
 options=async(req:Request,res:Response)=>{const u=await this.grantIdentity(req),root=(await this.store.db.ref().once('value')).val()||{};res.setHeader('Cache-Control','no-store');const rows=[];for(const type of ASSET_TYPES)for(const [id,a]of Object.entries<any>(root.assets?.[type]||{}))if(this.allowed(root,u.uid,type,id,u.admin===true||u.role==='admin'))rows.push({id,assetType:type,name:String(a.name||id),ownerId:a.ownerId,ownerName:String(root.backendusers?.[a.ownerId]?.displayName||a.ownerId),delegations:Object.entries<any>(root.assetDelegations?.[type]?.[id]||{}).filter(([,g])=>g.active===true&&g.ownerId===a.ownerId).map(([uid,g])=>({conciergeId:uid,email:g.email,displayName:g.displayName,permissions:g.permissions,updatedAt:g.updatedAt}))});return res.json(rows);};
 grant=async(req:Request,res:Response)=>{
  const u=await this.grantIdentity(req),{type,id}=this.scope(req),p=z.object({email:z.string().email().max(320),permissions}).strict().parse(req.body);let target:any;
  try{target=await this.store.auth.getUserByEmail(p.email.trim().toLowerCase());}catch(e:any){if(e.code==='auth/user-not-found')throw fail('concierge_account_required',404);throw e;}if(!/^[a-zA-Z0-9_-]{1,128}$/.test(target.uid)||['__proto__','prototype','constructor'].includes(target.uid))throw fail('invalid_concierge_id',400);if(target.disabled)throw fail('concierge_account_disabled');
  const audit=randomUUID(),now=new Date().toISOString();const result=await this.store.db.ref().transaction((root:any)=>{if(root===null)return null;if(!this.allowed(root,u.uid,type,id,u.admin===true||u.role==='admin'))return;const ownerId=root.assets[type][id].ownerId;if(target.uid===ownerId)return;
   root.assetDelegations??={};root.assetDelegations[type]??={};root.assetDelegations[type][id]??={};const previous=root.assetDelegations[type][id][target.uid]||null;const next={ownerId,conciergeId:target.uid,assetType:type,assetId:id,email:String(target.email||p.email).toLowerCase(),displayName:String(target.displayName||target.email||p.email),active:true,permissions:p.permissions,grantedBy:u.uid,createdAt:previous?.createdAt||now,updatedAt:now};root.assetDelegations[type][id][target.uid]=next;
   root.delegationAudit??={};root.delegationAudit[audit]={action:'grant',actorId:u.uid,ownerId,assetType:type,assetId:id,conciergeId:target.uid,previous,permissions:p.permissions,at:now};return root;
  },undefined,false);if(!result.committed||!result.snapshot.val()?.assetDelegations?.[type]?.[id]?.[target.uid]?.active)throw fail('delegation_not_allowed');return res.json({ok:true,conciergeId:target.uid});
 };
 revoke=async(req:Request,res:Response)=>{const u=await this.grantIdentity(req),{type,id}=this.scope(req),uid=z.string().regex(/^[a-zA-Z0-9_-]{1,128}$/).parse(req.params.conciergeId),audit=randomUUID(),now=new Date().toISOString();const result=await this.store.db.ref().transaction((root:any)=>{if(root===null)return null;if(!this.allowed(root,u.uid,type,id,u.admin===true||u.role==='admin'))return;const g=root.assetDelegations?.[type]?.[id]?.[uid];if(!g)return;g.active=false;g.revokedAt=now;g.revokedBy=u.uid;g.updatedAt=now;root.delegationAudit??={};root.delegationAudit[audit]={action:'revoke',actorId:u.uid,ownerId:root.assets[type][id].ownerId,assetType:type,assetId:id,conciergeId:uid,at:now};return root;},undefined,false);if(!result.committed||result.snapshot.val()?.assetDelegations?.[type]?.[id]?.[uid]?.active!==false)throw fail('delegation_not_allowed');return res.json({ok:true});};
 assets=async(req:Request,res:Response)=>{const{uid,root}=await this.identity(req);res.setHeader('Cache-Control','no-store');return res.json(delegatedAssets(root,uid));};
 bookings=async(req:Request,res:Response)=>{const{uid,root,claims}=await this.identity(req);const rows:any[]=[];for(const type of ASSET_TYPES)for(const [id,items]of Object.entries<any>(root.bookings?.[type]||{}))if(assetPermission(root,uid,type,id,'bookings',claims))for(const [key,b]of Object.entries<any>(items||{}))if(b?.id===key&&b.assetType===type&&b.assetId===id&&b.ownerId===root.assets[type][id].ownerId){const view=await reservationView(this.store,b);rows.push(b.ownerId===uid?view:conciergeBookingView(view));}res.setHeader('Cache-Control','no-store');return res.json(rows);};
 payments=async(req:Request,res:Response)=>{const{uid,root}=await this.identity(req);const rows=[];for(const [id,p]of Object.entries<any>(root.payments||{})){const parts=String(p.bookingPath||'').split('/');if(parts.length!==4||parts[0]!=='bookings')continue;const [,type,assetId,bookingId]=parts,b=root.bookings?.[type]?.[assetId]?.[bookingId],a=root.assets?.[type]?.[assetId];if(!b||b.id!==bookingId||b.ownerId!==a?.ownerId||p.bookingId!==bookingId||p.ownerId!==a.ownerId||p.assetId!==assetId||p.stripeConnectedAccountId!==b.stripeConnectedAccountId||!activeDelegation(root,uid,type,assetId)?.permissions?.payments)continue;rows.push({id,assetType:type,assetId,assetName:String(a.name||assetId),ownerId:a.ownerId,bookingId,kind:p.kind,status:p.status,amount:p.amount,currency:p.currency,stripeMode:p.stripeMode,createdAt:p.createdAt||null,refundedMinor:Number(p.cancellationRefund?.refunded||0)});}res.setHeader('Cache-Control','no-store');return res.json(rows);};
 customers=async(req:Request,res:Response)=>{const{uid,root}=await this.identity(req),scopes=delegatedAssets(root,uid).filter(a=>a.permissions.customers);const rows:any[]=[];
  for(const ownerId of new Set(scopes.map(a=>a.ownerId))){const owned=scopes.filter(a=>a.ownerId===ownerId),copy={...root,assets:{}} as any;for(const a of owned){copy.assets[a.assetType]??={};copy.assets[a.assetType][a.id]=root.assets[a.assetType][a.id];}
   for(const c of ownerCustomerRows(copy,ownerId)){c.bookings=c.bookings.map((b:any)=>({...b,canManageBookings:owned.some(a=>a.assetType===b.assetType&&a.id===b.assetId&&a.permissions.bookings),canViewPayments:owned.some(a=>a.assetType===b.assetType&&a.id===b.assetId&&a.permissions.payments),warranty:{...b.warranty,canCharge:false,charges:owned.some(a=>a.assetType===b.assetType&&a.id===b.assetId&&a.permissions.payments)?b.warranty.charges:[]}}));c.bookings.forEach((b:any)=>{if(!b.canViewPayments)b.warranty={limitMinor:b.warranty.limitMinor,canCharge:false,charges:[]};});c.payments=c.payments.filter((p:any)=>owned.some(a=>a.assetType===p.assetType&&a.id===p.assetId&&a.permissions.payments));rows.push({...c,ownerId,ownerName:String(root.backendusers?.[ownerId]?.displayName||ownerId)});}
  }res.setHeader('Cache-Control','no-store');return res.json(rows);
 };
}
